<script setup lang="ts">
import { computed, onUnmounted } from 'vue'
import { NButton } from 'naive-ui'
import { api } from '../../shared/api'
import { useResource, formatDate, formatBytes, percent } from '../../shared/ui/resource'
import { useRealtime } from '../../shared/realtime/useRealtime'
import { safeMediaUrl } from '../../shared/media/url'
import EmptyState from '../../shared/ui/EmptyState.vue'
import ErrorBanner from '../../shared/ui/ErrorBanner.vue'
import Icon from '../../shared/ui/Icon.vue'
import StatusBadge from '../../shared/ui/StatusBadge.vue'
const {data,loading,error,refresh}=useResource(api.dashboard)
const {data:runtime}=useResource(api.runtime)
const {connected}=useRealtime(()=>void refresh())
const clock=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})
const used=computed(()=>runtime.value?runtime.value.disk.used_bytes/runtime.value.disk.total_bytes*100:0)
const polling=setInterval(()=>void refresh(),15000);onUnmounted(()=>clearInterval(polling))
</script>
<template><div class="page-heading"><div><h1>快速监控看板</h1><p>实时掌握视频源、监控画面与事件动态</p></div><span class="clock">{{clock}}</span></div><ErrorBanner :error="error" @retry="refresh"/><div v-if="loading&&!data" class="loading-line" aria-label="正在加载看板"/><div class="stats-grid"><div class="panel stat"><div class="stat-icon"><Icon name="monitor" :size="27"/></div><div><div class="stat-label">视频源在线数</div><div class="stat-value">{{data?.counts.sources_online??'—'}} <small>/ {{data?.counts.sources_total??'—'}}</small></div><div class="stat-note">{{data?.counts.sources_total?'已接入视频源':'等待接入视频源'}}</div></div></div><div class="panel stat"><div class="stat-icon green"><Icon name="cpu" :size="27"/></div><div><div class="stat-label">GPU 使用率</div><div class="stat-value" style="font-size:26px">{{percent(runtime?.gpu_percent)}}</div><div class="stat-note">{{runtime?.gpu_percent==null?'尚无 GPU 采集器':'来自本机实测'}}</div></div></div><div class="panel stat"><div class="stat-icon purple"><Icon name="database" :size="27"/></div><div><div class="stat-label">存储空间</div><div class="stat-value" style="font-size:22px">{{runtime?formatBytes(runtime.disk.used_bytes):'—'}}</div><div class="stat-note">{{runtime?`共 ${formatBytes(runtime.disk.total_bytes)} · 已用 ${used.toFixed(1)}%`:'等待资源采样'}}</div></div></div><div class="panel stat"><div class="stat-icon orange"><Icon name="siren" :size="27"/></div><div><div class="stat-label">今日事件</div><div class="stat-value">{{data?.counts.today_events??'—'}}</div><div class="stat-note">{{data?.counts.active_runs??0}} 路任务运行中</div></div></div></div><div class="dashboard-main"><section class="panel"><div class="panel-title"><h2>实时监控画面 <small>（{{data?.sources.length??0}} 路）</small></h2><RouterLink to="/sources" style="font-size:12px">管理视频源 <span aria-hidden="true">›</span></RouterLink></div><div v-if="data?.sources.length" class="video-grid"><article v-for="source in data.sources.slice(0,4)" :key="source.id" class="source-tile"><RouterLink :to="`/sources/${source.id}`" class="tile-media"><img v-if="safeMediaUrl(source.thumbnail_url)" :src="safeMediaUrl(source.thumbnail_url)!" :alt="`${source.name} 视频缩略图`"/><Icon v-else :name="source.kind==='camera'?'camera':'film'"/><StatusBadge :value="source.status"/></RouterLink><div class="tile-footer"><RouterLink :to="`/sources/${source.id}`">{{source.name}}</RouterLink><Icon :name="source.kind==='camera'?'camera':'film'" :size="15"/></div></article></div><EmptyState v-else icon="video" title="还没有接入视频源" description="导入本地录像或连接现场摄像头，开始准备验证素材。" large><NButton size="small" type="primary" @click="$router.push('/sources')"><template #icon><Icon name="plus" :size="16"/></template>添加视频源</NButton></EmptyState><div style="display:flex;justify-content:space-between;margin-top:14px;font-size:10px;color:#8b99ad"><span>{{connected?'状态通知已连接':'状态通知重连中，定时刷新已启用'}}</span><span>画面预览请打开视频源详情</span></div></section><div class="stack"><section class="panel"><div class="panel-title"><h2>最近事件</h2><RouterLink to="/dashboard/events" style="font-size:12px">查看全部 ›</RouterLink></div><template v-if="data?.recent_events.length"><div v-for="event in data.recent_events.slice(0,5)" :key="event.id" class="event-row"><span class="dot" style="color:#e79549;margin-top:7px"/><div><h3>{{event.event_type}}</h3><p>{{event.source_name}} · {{formatDate(event.occurred_at)}}</p><p>{{event.reason}}</p></div></div></template><EmptyState v-else title="暂无事件记录" description="接入并运行监测任务后，事件会显示在这里。" compact icon="bell"/></section><section class="panel"><div class="panel-title"><h2>任务概览</h2><small>当前工作空间</small></div><div class="task-counts"><div>进行中<strong>{{data?.task_summary.running??0}}</strong></div><div>已完成<strong>{{data?.task_summary.completed??0}}</strong></div><div>等待中<strong>{{data?.task_summary.waiting??0}}</strong></div></div><p class="muted" style="font-size:10px;margin-top:13px">智能体草稿可在智能体管理中维护；监测执行服务尚未接入。</p></section></div></div><section class="panel quick-panel"><div class="panel-title"><h2>快捷操作</h2></div><div class="quick-grid"><RouterLink to="/sources" class="quick-card"><span class="stat-icon"><Icon name="plus"/></span><div><strong>添加视频源</strong><small>导入录像或接入摄像头</small></div></RouterLink><RouterLink to="/runtime" class="quick-card"><span class="stat-icon green"><Icon name="activity"/></span><div><strong>查看运行状态</strong><small>了解本机资源与服务</small></div></RouterLink><button class="quick-card" disabled title="任务创建模块将在后续版本接入"><span class="stat-icon purple"><Icon name="bot"/></span><div><strong>创建监测任务</strong><small>后续版本接入</small></div></button><RouterLink to="/settings/general" class="quick-card"><span class="stat-icon"><Icon name="settings"/></span><div><strong>系统设置</strong><small>维护运行与接入策略</small></div></RouterLink></div></section></template>
